previewCss:
.darma-loader-darma-b11-matrix-rain { --accent: var(--loader-color, #22c55e); --accent-2: var(--loader-secondary-color, #86efac); width: var(--loader-size, 84px); height: var(--loader-size, 84px); position: relative; overflow: hidden; border-radius: 10%; background: #0a0f0a; }
.darma-loader-darma-b11-matrix-rain span { position: absolute; top: 0; width: 13%; height: 42%; background: linear-gradient(transparent, var(--accent) 62%, color-mix(in srgb, #fff 60%, var(--accent-2))); border-radius: 4px; animation: darma-loader-darma-b11-matrix-rain-mrain calc(var(--loader-speed, 1s) * 1.6) linear infinite; }
.darma-loader-darma-b11-matrix-rain span:nth-child(1) { left: 6%; animation-duration: calc(var(--loader-speed, 1s) * 1.4); animation-delay: 0s; }
.darma-loader-darma-b11-matrix-rain span:nth-child(2) { left: 26%; animation-duration: calc(var(--loader-speed, 1s) * 2); animation-delay: calc(var(--loader-speed, 1s) * -.6); }
.darma-loader-darma-b11-matrix-rain span:nth-child(3) { left: 46%; animation-duration: calc(var(--loader-speed, 1s) * 1.7); animation-delay: calc(var(--loader-speed, 1s) * -1); }
.darma-loader-darma-b11-matrix-rain span:nth-child(4) { left: 66%; animation-duration: calc(var(--loader-speed, 1s) * 2.3); animation-delay: calc(var(--loader-speed, 1s) * -.3); }
.darma-loader-darma-b11-matrix-rain span:nth-child(5) { left: 84%; animation-duration: calc(var(--loader-speed, 1s) * 1.5); animation-delay: calc(var(--loader-speed, 1s) * -1.4); }
@keyframes darma-loader-darma-b11-matrix-rain-mrain { 0% { transform: translateY(-110%); } 100% { transform: translateY(255%); } }

